"""Writes fastapi_routes_gen.go: the Python gateway's routes as Starlette tries them, read from
the FastAPI app itself (app.main), so that the Go router (server.New) cannot drift from it.

FastAPI 0.139 keeps an included router as one entry (_IncludedRouter) whose routes are tried
in their order, depth first: the list below is that order, flattened. For each route: whether
it is a WebSocket route, its path as declared, its methods (a set: Starlette's Allow header
joins them in the set's order) and the regular expression Starlette matches the path with.

Run inside the gateway image with the gateway's sources mounted (see run.sh)."""
import json
import logging

logging.disable(logging.CRITICAL)

from fastapi.routing import APIRoute, _EffectiveRouteContext, _IncludedRouter  # noqa: E402
from starlette import routing  # noqa: E402

from app.main import app  # noqa: E402


def entry(route):
    if isinstance(route, _EffectiveRouteContext):
        if isinstance(route.original_route, APIRoute):
            return ("http", route.path, route.methods, route.path_regex.pattern)
        route = route.starlette_route
    if isinstance(route, routing.Route):
        return ("http", route.path, route.methods, route.path_regex.pattern)
    if isinstance(route, routing.WebSocketRoute):
        return ("ws", route.path, None, route.path_regex.pattern)
    raise SystemExit(f"a route the Go router does not know: {route!r}")


def walk(routes, out):
    for r in routes:
        if isinstance(r, _IncludedRouter):
            walk(r.effective_candidates(), out)
        else:
            out.append(entry(r))


if app.router._low_priority_routes:
    raise SystemExit("low-priority routes (frontend routes): the Go router does not try them")
def table(name, doc, routes):
    out = []
    walk(routes, out)
    lines = ["", f"// {name} {doc}", f"var {name} = []pyRoute{{"]
    for kind, path, methods, regex in out:
        m = "nil" if methods is None else "[]string{" + ", ".join(json.dumps(x) for x in sorted(methods)) + "}"
        lines.append(f"\t{{ws: {'true' if kind == 'ws' else 'false'}, path: {json.dumps(path)}, methods: {m}, regex: {json.dumps(regex)}}},")
    lines.append("}")
    print(f"{name}: {len(out)} routes")
    return lines


# the notebooks' own host (routes/notebook_proxy.py install): an application of its own
(host,) = [m.kwargs["notebooks"] for m in app.user_middleware if m.cls.__name__ == "NotebooksHost"]
if app.router.redirect_slashes is not True or host.router.redirect_slashes is not False:
    raise SystemExit("redirect_slashes: the Go router expects it on for the API (at the root) and off for the notebooks' host")
lines = ["// Code generated by testdata/gen_routes.py; DO NOT EDIT.", "", "package server"]
lines += table("fastAPIRoutes", "are the Python gateway's routes in the order Starlette tries them.", app.router.routes)
lines += table("notebooksHostRoutes", "are the routes of the notebooks' own host (NOTEBOOKS__ORIGIN), in their order.",
               host.router.routes)
open("/server/fastapi_routes_gen.go", "w").write("\n".join(lines) + "\n")
